def _eq(a, b):
    try:
        if type(a) != type(b):
            return False
        if 'all' in dir(a==b):
            return (a == b).all()
        return a == b
    except Exception as e:
        print(f'Warning: eq error, {e}, {a}, {b}, {type(a)}, {type(b)}')
        if len(a) != len(b):
            return False
        if type(a) != type(b):
            return False
        return all([a_ == b_ for a_, b_ in zip(a, b)])
