def pickable(data):
    try:
        pickle.dumps(data)
        return data
    except:
        pass
    if isinstance(data, dict):
        return {
            k: pickable(v)
            for k, v in data.items()
        }
    elif isinstance(data, list):
        return [
            pickable(v)
            for v in data
        ]
    elif isinstance(data, tuple):
        return tuple(
            pickable(v)
            for v in data
        )
    elif isinstance(data, set):
        return {
            pickable(v)
            for v in data
        }
    elif isinstance(data, str):
        return data
    elif isinstance(data, int):
        return data
    elif isinstance(data, float):
        return data
    elif isinstance(data, bool):
        return data
    elif data is None:
        return data
    else:
        return str(data)

def itemnum(data):
    if isinstance(data, dict):
        return sum([itemnum(v) for v in data.values()])
    elif isinstance(data, list):
        return sum([itemnum(v) for v in data])
    elif isinstance(data, tuple):
        return sum([itemnum(v) for v in data])
    elif isinstance(data, set):
        return sum([itemnum(v) for v in data])
    elif isinstance(data, str):
        return len(data)
    else:
        return 1

import numpy as np


class AtariEnvRecorder:
    def __init__(self, recording_with_bb=False):
        self.recording = False
        self.frames = []
        self.recording_with_bb = recording_with_bb

    def record(self, atari_env):
        if self.recording_with_bb:
            frame = atari_env.env.render()
            frame = np.rot90(frame, k=-1)
            frame = np.fliplr(frame)
        else:
            frame = atari_env.env._env.render()
        self.frames.append(frame)

    def start_recording(self):
        self.recording = True
        self.frames = []

    def end_recording(self):
        res = self.frames

        self.recording = False
        self.frames = []
        return res

